// ---------------------------------------------------------------------------
// SEAMLESS REGIONS — natural-size 30px-snapped region placement, mixed border
// porosity (open blended frontiers, broken divides, and tactical chokepoints),
// sanctuary gates, and spatial ground-theme blending.
//
// Zones remain first-class ZoneDefs generated by main's unchanged generateLayout
// pipeline, mounted onto one continuous surface plane without threshold rebasing
// or loading screens.
// ---------------------------------------------------------------------------

import { clamp, vec, type Vec2 } from '../core/math';
import { Rng } from '../core/rng';
import { START_ZONE, objectiveSeals, type ZoneDef, type ZoneExitDef, type ZoneTheme } from '../data/zones';
import { zoneKindOf } from '../data/zoneKinds';
import { siteZoneExits } from '../engine/exitSiting';
import type { Doodad, KnownDoodadKind } from '../engine/levelgen';
import { BIOMES } from './biomes';
import { type Dir, OPP_DIR } from './coords';
import { DEFAULT_CELL } from './gridWalk';
import type { TiledWalkField } from './tiledWalk';

export const SEAMLESS_CFG = {
  cellPx: DEFAULT_CELL,        // 30px lattice alignment
  snapPx: DEFAULT_CELL * 2,    // 60px box alignment (half-dimensions stay cell-aligned)
  townReserveW: 2640,          // Fits TOWN_TIERS[3] township (2600×1800) with origin at (0,0)
  townReserveH: 1800,
  ringInPx: 1450,              // Mount neighbor regions when hero is within this distance of rect
  ringOutPx: 2650,             // Unmount/demote to ZoneMemory beyond this distance (hysteresis)
  liveAiRadiusPx: 1450,        // Full-cadence AI radius around player seats; beyond = drowsy
  drowsyCadence: 4,            // Divide idle distant-region AI ticks by 4
  blendBandPx: 260,            // Cross-border ground/wall theme blend band width (world px)
  mouthHalfW: 105,             // Standard open road mouth half-width (210px clear opening)
  sanctuaryGateHalfW: 105,     // Lastlight town gate opening half-width
  passHalfW: 120,              // Carved corridor half-width when loop topology leaves a gap
  borderWallThickPx: 60,       // 2 walk cells thick perimeter barrier on enclosed borders
  mountBudgetPerFrame: 1,      // Max background region mounts per live frame
  skirmishCooldownSec: 75,     // Minimum interval between cross-border faction raid spawns
} as const;

export function snapCell(v: number): number {
  return Math.round(v / SEAMLESS_CFG.cellPx) * SEAMLESS_CFG.cellPx;
}

export function snapBox(v: number): number {
  return Math.max(SEAMLESS_CFG.snapPx * 4, Math.round(v / SEAMLESS_CFG.snapPx) * SEAMLESS_CFG.snapPx);
}

/** Deterministic string hash (FNV-1a 32-bit). */
export function hashKey(s: string, salt = 0x811c9dc5): number {
  let h = salt >>> 0;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h >>> 0;
}

/** Is a ZoneDef part of the continuous surface plane (vs. subterranean caves,
 *  isolated pockets, sea-voyage ports, or alternate dimensions)? */
export function isSeamlessSurfaceZone(def: ZoneDef | undefined | null): boolean {
  if (!def) return false;
  if ((def.dimension ?? 'surface') !== 'surface') return false;
  if (def.caveDepth != null) return false;
  if (def.boundless || def.pocket || def.aquatic) return false;
  if (def.kind === 'port' || zoneKindOf(def)?.staticExits) return false;
  if (def.layoutType === 'unmade_vault') return false;
  return true;
}

export interface RegionSeatRect {
  zoneId: string;
  /** World-space origin of the zone's active layout (0,0 -> originPx). */
  originPx: { x: number; y: number };
  /** Active layout dimensions (snapped to 60px). */
  w: number;
  h: number;
  /** Reserved non-overlapping plot box (equals [originPx..originPx+w/h], except
   *  Lastlight which reserves townReserveW×H so town tier upgrades never collide). */
  plot: { x0: number; y0: number; x1: number; y1: number };
}

export type BorderStyle =
  | 'sanctuary_gate'   // Town palisade + lantern-flanked open watch-gate
  | 'sealed_gate'      // Locked exit (Holdfast / Harborhold / Boss seal) — physical gate until unlocked
  | 'open_frontier'    // Wide porous border (65–80% open) + smooth ground blend
  | 'broken_divide'    // Partial natural ridge/wall/copse/brook with 2–3 tactical openings
  | 'chokepoint_pass'; // Strong perimeter barrier forcing travel through a dramatic road mouth

export interface SeamCrossing {
  key: string;
  aId: string;
  bId: string;
  sideOnA: Dir;
  sideOnB: Dir;
  style: BorderStyle;
  /** World-space mouth anchor on A's active perimeter. */
  mouthA: Vec2;
  /** World-space mouth anchor on B's active perimeter. */
  mouthB: Vec2;
  /** Additional flanking breach centers (world-space midpoints) for broken_divide / open_frontier. */
  extraGaps: { a: Vec2; b: Vec2; halfW: number }[];
  /** True when A and B's active boxes butt directly (<= 60px gap); false when connected by a pass corridor. */
  flush: boolean;
  /** Optional lock key or sealing condition keeping this crossing barred until met. */
  locked: boolean;
}

export interface ThemeBlendSample {
  primary: ZoneTheme;
  secondary: ZoneTheme | null;
  mix: number;
  seed: number;
}

const OPEN_BIOMES = new Set([
  'field', 'downs', 'desert', 'steppes', 'tundra', 'beach', 'farmland', 'courtland', 'scald',
]);

const ENCLOSED_BIOMES = new Set([
  'forest', 'gloamwood', 'jungle', 'highland', 'metropolis', 'manor',
  'ossuary', 'ruin', 'sepulcher', 'durance', 'warfront', 'flesh', 'caul', 'cavern',
]);

function classifyBiomePorosity(biome: string | undefined): 'open' | 'semi' | 'enclosed' {
  if (!biome) return 'open';
  if (BIOMES[biome]?.enclave || ENCLOSED_BIOMES.has(biome)) return 'enclosed';
  if (OPEN_BIOMES.has(biome)) return 'open';
  return 'semi';
}

/** Pick appropriate natural barrier doodad kind for a region's theme/biome. */
function borderPropKindFor(def: ZoneDef): KnownDoodadKind {
  const b = def.biome ?? '';
  if (b === 'forest' || b === 'grove' || b === 'garden') return 'forest_oak';
  if (b === 'gloamwood') return 'gloam_oak';
  if (b === 'jungle') return 'palm';
  if (b === 'taiga') return 'conifer';
  if (b === 'tundra') return 'ice_spike';
  if (b === 'desert' || b === 'courtland' || b === 'sepulcher') return 'rock';
  if (b === 'farmland' || b === 'field') return 'tree';
  if (b === 'metropolis' || b === 'manor' || b === 'ruin' || b === 'ossuary') return 'wall';
  if (def.id === START_ZONE) return 'wall';
  return 'rock';
}

function rectsOverlap(
  a: { x0: number; y0: number; x1: number; y1: number },
  b: { x0: number; y0: number; x1: number; y1: number },
  pad = 0,
): boolean {
  return a.x0 < b.x1 + pad && a.x1 > b.x0 - pad && a.y0 < b.y1 + pad && a.y1 > b.y0 - pad;
}

export function pointToRectDist(x: number, y: number, r: { x0: number; y0: number; x1: number; y1: number }): number {
  const dx = x < r.x0 ? r.x0 - x : x > r.x1 ? x - r.x1 : 0;
  const dy = y < r.y0 ? r.y0 - y : y > r.y1 ? y - r.y1 : 0;
  return Math.hypot(dx, dy);
}

function edgeDirBetween(a: ZoneDef, b: ZoneDef, explicitSide?: Dir): Dir {
  if (explicitSide) return explicitSide;
  const dx = b.map.x - a.map.x, dy = b.map.y - a.map.y;
  if (Math.abs(dx) >= Math.abs(dy)) return dx >= 0 ? 'e' : 'w';
  return dy >= 0 ? 's' : 'n';
}

function pairKey(a: string, b: string): string {
  return a < b ? `${a}|${b}` : `${b}|${a}`;
}

/** Persistent layout planner mapping surface ZoneDefs to non-overlapping
 *  30px-aligned world boxes and resolving shared border seams. */
export class SeamlessAtlasLayout {
  readonly seats = new Map<string, RegionSeatRect>();
  readonly seams = new Map<string, SeamCrossing>();
  private worldSeed: number;

  constructor(worldSeed: number) {
    this.worldSeed = worldSeed >>> 0;
  }

  reset(worldSeed?: number): void {
    if (worldSeed !== undefined) this.worldSeed = worldSeed >>> 0;
    this.seats.clear();
    this.seams.clear();
  }

  /** Refresh town active dimensions inside its reserved plot if Lastlight grew
   *  across town tiers. */
  syncTownSize(townDef: ZoneDef): void {
    const existing = this.seats.get(START_ZONE);
    if (!existing) return;
    existing.w = Math.min(SEAMLESS_CFG.townReserveW, snapBox(townDef.size.w));
    existing.h = Math.min(SEAMLESS_CFG.townReserveH, snapBox(townDef.size.h));
  }

  /** Seat any newly charted surface ZoneDefs reachable from START_ZONE (or
   *  floating/directed surface zones) without moving already-seated regions. */
  ensureSeats(zoneMap: Record<string, ZoneDef>, isLinkLocked?: (from: ZoneDef, e: ZoneExitDef, idx: number) => boolean): void {
    const town = zoneMap[START_ZONE];
    if (town) siteZoneExits(town);
    if (town && !this.seats.has(START_ZONE)) {
      const tw = Math.min(SEAMLESS_CFG.townReserveW, snapBox(town.size.w));
      const th = Math.min(SEAMLESS_CFG.townReserveH, snapBox(town.size.h));
      this.seats.set(START_ZONE, {
        zoneId: START_ZONE,
        originPx: { x: 0, y: 0 },
        w: tw,
        h: th,
        plot: { x0: 0, y0: 0, x1: SEAMLESS_CFG.townReserveW, y1: SEAMLESS_CFG.townReserveH },
      });
    } else if (town) {
      this.syncTownSize(town);
    }

    // BFS from already-seated regions in deterministic id + exit order so
    // layout coordinates are repeatable across save/resume.
    let progress = true;
    while (progress) {
      progress = false;
      const seatedIds = [...this.seats.keys()];
      for (const aId of seatedIds) {
        const aDef = zoneMap[aId];
        const aSeat = this.seats.get(aId);
        if (!aDef || !aSeat) continue;
        // Count siblings on each cardinal side so multiple exits on one side fan cleanly.
        const sideCounts: Record<Dir, number> = { n: 0, s: 0, e: 0, w: 0 };
        const sideTotals: Record<Dir, number> = { n: 0, s: 0, e: 0, w: 0 };
        for (const ex of aDef.exits) {
          if (ex.to === '?' || ex.crossDim) continue;
          const bDef = zoneMap[ex.to];
          if (!isSeamlessSurfaceZone(bDef)) continue;
          sideTotals[edgeDirBetween(aDef, bDef!, ex.side)]++;
        }

        for (const ex of aDef.exits) {
          if (ex.to === '?' || ex.crossDim) continue;
          const bDef = zoneMap[ex.to];
          if (!bDef || !isSeamlessSurfaceZone(bDef)) continue;
          const dir = edgeDirBetween(aDef, bDef, ex.side);
          const slotIdx = sideCounts[dir]++;
          const slotTot = Math.max(1, sideTotals[dir]);

          if (!this.seats.has(bDef.id)) {
            const placed = this.placeNeighbor(aSeat, aDef, bDef, dir, slotIdx, slotTot);
            this.seats.set(bDef.id, placed);
            progress = true;
          }
        }
      }
    }

    // Rebuild/update seam descriptors for all linked seated pairs.
    for (const [aId, aSeat] of this.seats) {
      const aDef = zoneMap[aId];
      if (!aDef) continue;
      for (let i = 0; i < aDef.exits.length; i++) {
        const ex = aDef.exits[i];
        if (ex.to === '?' || ex.crossDim) continue;
        const bDef = zoneMap[ex.to];
        const bSeat = bDef ? this.seats.get(bDef.id) : undefined;
        if (!bDef || !bSeat) continue;
        const pk = pairKey(aId, bDef.id);
        const locked = !!(isLinkLocked?.(aDef, ex, i)
          || bDef.exits.some((bx, bi) => bx.to === aId && isLinkLocked?.(bDef, bx, bi)));
        const existing = this.seams.get(pk);
        if (!existing) {
          this.seams.set(pk, this.buildSeam(aDef, aSeat, bDef, bSeat, ex.side, locked));
        } else {
          existing.locked = locked;
          if (existing.style === 'sealed_gate' && !locked) {
            existing.style = this.rollUnlockedStyle(aDef, bDef, pk);
          } else if (locked && existing.style !== 'sanctuary_gate') {
            existing.style = 'sealed_gate';
          }
        }
      }
    }
  }

  private placeNeighbor(
    aSeat: RegionSeatRect,
    aDef: ZoneDef,
    bDef: ZoneDef,
    dir: Dir,
    slotIdx: number,
    slotTot: number,
  ): RegionSeatRect {
    const bw = snapBox(bDef.size.w);
    const bh = snapBox(bDef.size.h);
    const ap = aSeat.plot;
    const aMidX = (ap.x0 + ap.x1) / 2;
    const aMidY = (ap.y0 + ap.y1) / 2;

    // Fan multiple exits on the same side + subtle map-coordinate lean.
    const fanFrac = slotTot > 1 ? (slotIdx / (slotTot - 1) - 0.5) : 0;
    const mapLeanX = clamp((bDef.map.x - aDef.map.x) * 8, -420, 420);
    const mapLeanY = clamp((bDef.map.y - aDef.map.y) * 8, -420, 420);

    const basePos = (pushPx: number, lateralPx: number): { x0: number; y0: number } => {
      if (dir === 'e') return { x0: ap.x1 + pushPx, y0: snapCell(aMidY - bh / 2 + fanFrac * (bh + 180) + lateralPx + mapLeanY * 0.25) };
      if (dir === 'w') return { x0: ap.x0 - bw - pushPx, y0: snapCell(aMidY - bh / 2 + fanFrac * (bh + 180) + lateralPx + mapLeanY * 0.25) };
      if (dir === 's') return { x0: snapCell(aMidX - bw / 2 + fanFrac * (bw + 180) + lateralPx + mapLeanX * 0.25), y0: ap.y1 + pushPx };
      return { x0: snapCell(aMidX - bw / 2 + fanFrac * (bw + 180) + lateralPx + mapLeanX * 0.25), y0: ap.y0 - bh - pushPx };
    };

    const free = (x0: number, y0: number): boolean => {
      const cand = { x0, y0, x1: x0 + bw, y1: y0 + bh };
      for (const other of this.seats.values()) {
        if (rectsOverlap(cand, other.plot, 0)) return false;
      }
      return true;
    };

    // 1. Try flush edge-to-edge attachment first (with small lateral slides so
    //    shared border overlap stays generous >= 360px).
    const maxLateralFlush = dir === 'e' || dir === 'w'
      ? Math.max(0, (ap.y1 - ap.y0 + bh) / 2 - 420)
      : Math.max(0, (ap.x1 - ap.x0 + bw) / 2 - 420);
    for (let lat = 0; lat <= maxLateralFlush; lat += SEAMLESS_CFG.snapPx) {
      for (const sign of lat === 0 ? [1] : [1, -1]) {
        const { x0, y0 } = basePos(0, lat * sign);
        if (free(x0, y0)) {
          return {
            zoneId: bDef.id,
            originPx: { x: x0, y: y0 },
            w: bw,
            h: bh,
            plot: { x0, y0, x1: x0 + bw, y1: y0 + bh },
          };
        }
      }
    }

    // 2. Graph loop / crowded-side fallback: step outward cleanly in 120px increments
    //    (connected seamlessly via a carved Scenic Pass corridor).
    for (let push = 120; push <= 9600; push += 120) {
      for (let lat = 0; lat <= push * 1.2; lat += 120) {
        for (const sign of lat === 0 ? [1] : [1, -1]) {
          const { x0, y0 } = basePos(push, lat * sign);
          if (free(x0, y0)) {
            return {
              zoneId: bDef.id,
              originPx: { x: x0, y: y0 },
              w: bw,
              h: bh,
              plot: { x0, y0, x1: x0 + bw, y1: y0 + bh },
            };
          }
        }
      }
    }

    const fallback = basePos(9720, 0);
    return {
      zoneId: bDef.id,
      originPx: { x: fallback.x0, y: fallback.y0 },
      w: bw,
      h: bh,
      plot: { x0: fallback.x0, y0: fallback.y0, x1: fallback.x0 + bw, y1: fallback.y0 + bh },
    };
  }

  private rollUnlockedStyle(aDef: ZoneDef, bDef: ZoneDef, pk: string): BorderStyle {
    if (aDef.objective.kind === 'safe' || bDef.objective.kind === 'safe') return 'sanctuary_gate';
    if (objectiveSeals(aDef.objective) || objectiveSeals(bDef.objective)) return 'chokepoint_pass';

    const rng = new Rng((this.worldSeed ^ hashKey(pk, 0x5ea3b02d)) >>> 0);
    const pa = classifyBiomePorosity(aDef.biome);
    const pb = classifyBiomePorosity(bDef.biome);
    const roll = rng.next();

    if (pa === 'enclosed' || pb === 'enclosed') {
      // Rugged / walled / forested biomes lean heavily enclosed, occasionally leaving 2 breaches.
      return roll < 0.78 ? 'chokepoint_pass' : 'broken_divide';
    }
    if (pa === 'open' && pb === 'open') {
      // Open-biome mixture (Ruling A3): mostly wide blended frontiers & broken divides,
      // tempered with ~22% full navigational chokepoints even within-biome!
      if (roll < 0.48) return 'open_frontier';
      if (roll < 0.78) return 'broken_divide';
      return 'chokepoint_pass';
    }
    // Mixed / semi-open biomes: balanced spread across all three.
    if (roll < 0.22) return 'open_frontier';
    if (roll < 0.60) return 'broken_divide';
    return 'chokepoint_pass';
  }

  private buildSeam(
    aDef: ZoneDef,
    aSeat: RegionSeatRect,
    bDef: ZoneDef,
    bSeat: RegionSeatRect,
    hintSide: Dir | undefined,
    locked: boolean,
  ): SeamCrossing {
    const pk = pairKey(aDef.id, bDef.id);
    const style: BorderStyle = (aDef.objective.kind === 'safe' || bDef.objective.kind === 'safe')
      ? 'sanctuary_gate'
      : locked
        ? 'sealed_gate'
        : this.rollUnlockedStyle(aDef, bDef, pk);

    const aBox = {
      x0: aSeat.originPx.x, y0: aSeat.originPx.y,
      x1: aSeat.originPx.x + aSeat.w, y1: aSeat.originPx.y + aSeat.h,
    };
    const bBox = {
      x0: bSeat.originPx.x, y0: bSeat.originPx.y,
      x1: bSeat.originPx.x + bSeat.w, y1: bSeat.originPx.y + bSeat.h,
    };

    const aCenter = vec((aBox.x0 + aBox.x1) / 2, (aBox.y0 + aBox.y1) / 2);
    const bCenter = vec((bBox.x0 + bBox.x1) / 2, (bBox.y0 + bBox.y1) / 2);
    const dx = bCenter.x - aCenter.x, dy = bCenter.y - aCenter.y;

    let sideOnA: Dir = hintSide ?? (Math.abs(dx) >= Math.abs(dy) ? (dx >= 0 ? 'e' : 'w') : (dy >= 0 ? 's' : 'n'));
    // Prefer true geometric facing between the seated active boxes.
    if (bBox.x0 >= aBox.x1 - 30 && Math.min(aBox.y1, bBox.y1) - Math.max(aBox.y0, bBox.y0) >= 240) sideOnA = 'e';
    else if (aBox.x0 >= bBox.x1 - 30 && Math.min(aBox.y1, bBox.y1) - Math.max(aBox.y0, bBox.y0) >= 240) sideOnA = 'w';
    else if (bBox.y0 >= aBox.y1 - 30 && Math.min(aBox.x1, bBox.x1) - Math.max(aBox.x0, bBox.x0) >= 240) sideOnA = 's';
    else if (aBox.y0 >= bBox.y1 - 30 && Math.min(aBox.x1, bBox.x1) - Math.max(aBox.x0, bBox.x0) >= 240) sideOnA = 'n';
    const sideOnB: Dir = OPP_DIR[sideOnA];

    const margin = 210;
    let mouthA: Vec2;
    let mouthB: Vec2;
    let flush = false;
    const extraGaps: { a: Vec2; b: Vec2; halfW: number }[] = [];
    const rng = new Rng((this.worldSeed ^ hashKey(pk, 0x91e10da5)) >>> 0);

    if (sideOnA === 'e' || sideOnA === 'w') {
      const ovLo = Math.max(aBox.y0 + margin, bBox.y0 + margin);
      const ovHi = Math.min(aBox.y1 - margin, bBox.y1 - margin);
      const ax = sideOnA === 'e' ? aBox.x1 : aBox.x0;
      const bx = sideOnA === 'e' ? bBox.x0 : bBox.x1;
      flush = Math.abs(bx - ax) <= 60 && ovHi > ovLo;
      const aSitedEx = aDef.exitSiting ? aDef.exits.find(e => e.to === bDef.id) : undefined;
      const bSitedEx = bDef.exitSiting ? bDef.exits.find(e => e.to === aDef.id) : undefined;
      if (aSitedEx?.at !== undefined || bSitedEx?.at !== undefined) {
        if (aSitedEx?.at !== undefined) {
          mouthA = vec(ax, snapCell(aBox.y0 + aSitedEx.at * aSeat.h));
          mouthB = vec(bx, snapCell(clamp(mouthA.y, bBox.y0 + margin, bBox.y1 - margin)));
        } else {
          mouthB = vec(bx, snapCell(bBox.y0 + bSitedEx!.at! * bSeat.h));
          mouthA = vec(ax, snapCell(clamp(mouthB.y, aBox.y0 + margin, aBox.y1 - margin)));
        }
      } else if (ovHi > ovLo) {
        const midY = snapCell(clamp((ovLo + ovHi) / 2 + rng.range(-0.18, 0.18) * (ovHi - ovLo), ovLo, ovHi));
        mouthA = vec(ax, midY);
        mouthB = vec(bx, midY);
        const span = ovHi - ovLo;
        if (flush && style === 'open_frontier' && span >= 360) {
          // Wide porous opening covering 65–75% of the shared border!
          extraGaps.push({
            a: vec(ax, (ovLo + ovHi) / 2),
            b: vec(bx, (ovLo + ovHi) / 2),
            halfW: Math.round((span * rng.range(0.33, 0.39)) / 30) * 30,
          });
        } else if (flush && style === 'broken_divide' && span >= 540) {
          const off1 = snapCell(clamp(midY - span * 0.34, ovLo, ovHi));
          const off2 = snapCell(clamp(midY + span * 0.34, ovLo, ovHi));
          if (Math.abs(off1 - midY) >= 180) extraGaps.push({ a: vec(ax, off1), b: vec(bx, off1), halfW: 85 });
          if (Math.abs(off2 - midY) >= 180) extraGaps.push({ a: vec(ax, off2), b: vec(bx, off2), halfW: 85 });
        }
      } else {
        mouthA = vec(ax, snapCell(clamp(bCenter.y, aBox.y0 + margin, aBox.y1 - margin)));
        mouthB = vec(bx, snapCell(clamp(aCenter.y, bBox.y0 + margin, bBox.y1 - margin)));
      }
    } else {
      const ovLo = Math.max(aBox.x0 + margin, bBox.x0 + margin);
      const ovHi = Math.min(aBox.x1 - margin, bBox.x1 - margin);
      const ay = sideOnA === 's' ? aBox.y1 : aBox.y0;
      const by = sideOnA === 's' ? bBox.y0 : bBox.y1;
      flush = Math.abs(by - ay) <= 60 && ovHi > ovLo;
      const aSitedEx = aDef.exitSiting ? aDef.exits.find(e => e.to === bDef.id) : undefined;
      const bSitedEx = bDef.exitSiting ? bDef.exits.find(e => e.to === aDef.id) : undefined;
      if (aSitedEx?.at !== undefined || bSitedEx?.at !== undefined) {
        if (aSitedEx?.at !== undefined) {
          mouthA = vec(snapCell(aBox.x0 + aSitedEx.at * aSeat.w), ay);
          mouthB = vec(snapCell(clamp(mouthA.x, bBox.x0 + margin, bBox.x1 - margin)), by);
        } else {
          mouthB = vec(snapCell(bBox.x0 + bSitedEx!.at! * bSeat.w), by);
          mouthA = vec(snapCell(clamp(mouthB.x, aBox.x0 + margin, aBox.x1 - margin)), ay);
        }
      } else if (ovHi > ovLo) {
        const midX = snapCell(clamp((ovLo + ovHi) / 2 + rng.range(-0.18, 0.18) * (ovHi - ovLo), ovLo, ovHi));
        mouthA = vec(midX, ay);
        mouthB = vec(midX, by);
        const span = ovHi - ovLo;
        if (flush && style === 'open_frontier' && span >= 360) {
          extraGaps.push({
            a: vec((ovLo + ovHi) / 2, ay),
            b: vec((ovLo + ovHi) / 2, by),
            halfW: Math.round((span * rng.range(0.33, 0.39)) / 30) * 30,
          });
        } else if (flush && style === 'broken_divide' && span >= 540) {
          const off1 = snapCell(clamp(midX - span * 0.34, ovLo, ovHi));
          const off2 = snapCell(clamp(midX + span * 0.34, ovLo, ovHi));
          if (Math.abs(off1 - midX) >= 180) extraGaps.push({ a: vec(off1, ay), b: vec(off1, by), halfW: 85 });
          if (Math.abs(off2 - midX) >= 180) extraGaps.push({ a: vec(off2, ay), b: vec(off2, by), halfW: 85 });
        }
      } else {
        mouthA = vec(snapCell(clamp(bCenter.x, aBox.x0 + margin, aBox.x1 - margin)), ay);
        mouthB = vec(snapCell(clamp(aCenter.x, bBox.x0 + margin, bBox.x1 - margin)), by);
      }
    }

    return { key: pk, aId: aDef.id, bId: bDef.id, sideOnA, sideOnB, style, mouthA, mouthB, extraGaps, flush, locked };
  }

  /** Local (0..w, 0..h) exit anchor positions for `def.exits` so `generateLayout`
   *  routes internal roads and clearways directly to the shared seam mouths!
   *  Returns `undefined` for uncharted `'?'` or non-seamless exits so `placeExit`
   *  keeps its natural non-overlapping edge spacing. */
  localExitPositionsFor(def: ZoneDef, zoneMap: Record<string, ZoneDef>): (Vec2 | undefined)[] {
    const seat = this.seats.get(def.id);
    if (!seat) return [];
    const out: (Vec2 | undefined)[] = [];
    const inset = 64;
    for (const ex of def.exits) {
      if (ex.to !== '?' && !ex.crossDim && zoneMap[ex.to]) {
        const seam = this.seams.get(pairKey(def.id, ex.to));
        if (seam) {
          const worldMouth = seam.aId === def.id ? seam.mouthA : seam.mouthB;
          out.push(vec(
            clamp(worldMouth.x - seat.originPx.x, inset, seat.w - inset),
            clamp(worldMouth.y - seat.originPx.y, inset, seat.h - inset),
          ));
          continue;
        }
      }
      out.push(undefined);
    }
    return out;
  }

  /** All seams incident to `zoneId`. */
  seamsFor(zoneId: string): SeamCrossing[] {
    const out: SeamCrossing[] = [];
    for (const s of this.seams.values()) {
      if (s.aId === zoneId || s.bId === zoneId) out.push(s);
    }
    return out;
  }

  /** Compose perimeter walls, open mouths, sanctuary watch-gates, and pass
   *  corridors for a freshly mounted region `def`, returning decorative/blocking
   *  border doodads (tagged with `regionId: def.id`). */
  composeRegionBorders(
    def: ZoneDef,
    seat: RegionSeatRect,
    walk: TiledWalkField,
    mountedIds: ReadonlySet<string>,
    liveDoodads?: Doodad[],
  ): Doodad[] {
    const borderDoodads: Doodad[] = [];
    const x0 = seat.originPx.x, y0 = seat.originPx.y;
    const x1 = x0 + seat.w, y1 = y0 + seat.h;
    const thick = def.id === START_ZONE ? DEFAULT_CELL : SEAMLESS_CFG.borderWallThickPx;
    const seams = this.seamsFor(def.id);

    // 1. Seal the 4 outer edges of this region's active box with a 2-cell solid
    //    perimeter band first, then carve open every unlocked mouth / frontier span!
    const wallKind = def.id === START_ZONE ? 'wall' : 'wall';
    walk.fillRegion(x0, y0, x1 - 0.1, y0 + thick - 0.1, wallKind, true, def.id);
    walk.fillRegion(x0, y1 - thick, x1 - 0.1, y1 - 0.1, wallKind, true, def.id);
    walk.fillRegion(x0, y0, x0 + thick - 0.1, y1 - 0.1, wallKind, true, def.id);
    walk.fillRegion(x1 - thick, y0, x1 - 0.1, y1 - 0.1, wallKind, true, def.id);

    // Collect open intervals along each side so border prop scatter skips them cleanly.
    const openSpans: Record<Dir, { lo: number; hi: number }[]> = { n: [], s: [], e: [], w: [] };
    const recordSpan = (side: Dir, center: number, hw: number): void => {
      openSpans[side].push({ lo: center - hw, hi: center + hw });
    };

    const carveSideOpening = (side: Dir, mouth: Vec2, halfW: number): void => {
      const deep = thick + 90; // punch cleanly into the interior walkable mesh
      if (side === 'e') {
        walk.fillRegion(x1 - deep, mouth.y - halfW, x1 + 30, mouth.y + halfW, 'ground', true, def.id);
        recordSpan('e', mouth.y, halfW + 36);
      } else if (side === 'w') {
        walk.fillRegion(x0 - 30, mouth.y - halfW, x0 + deep, mouth.y + halfW, 'ground', true, def.id);
        recordSpan('w', mouth.y, halfW + 36);
      } else if (side === 's') {
        walk.fillRegion(mouth.x - halfW, y1 - deep, mouth.x + halfW, y1 + 30, 'ground', true, def.id);
        recordSpan('s', mouth.x, halfW + 36);
      } else {
        walk.fillRegion(mouth.x - halfW, y0 - 30, mouth.x + halfW, y0 + deep, 'ground', true, def.id);
        recordSpan('n', mouth.x, halfW + 36);
      }
    };

    // 2. Carve mouths & road bridges for every seam incident to `def`.
    for (const seam of seams) {
      const isA = seam.aId === def.id;
      const otherId = isA ? seam.bId : seam.aId;
      const mySide = isA ? seam.sideOnA : seam.sideOnB;
      const myMouth = isA ? seam.mouthA : seam.mouthB;
      const otherMouth = isA ? seam.mouthB : seam.mouthA;

      if (!seam.locked) {
        const hw = seam.style === 'sanctuary_gate'
          ? SEAMLESS_CFG.sanctuaryGateHalfW
          : SEAMLESS_CFG.mouthHalfW;
        carveSideOpening(mySide, myMouth, hw);
        for (const g of seam.extraGaps) {
          carveSideOpening(mySide, isA ? g.a : g.b, g.halfW);
        }

        // When both sides of the seam are mounted, stitch the exact crossing
        // (direct flush bridge or scenic pass corridor when separated, including
        // Lastlight's approach lane across its town reserve!).
        if (mountedIds.has(otherId)) {
          const bridgeHw = seam.flush ? hw : SEAMLESS_CFG.passHalfW;
          const outVec = mySide === 'e' ? vec(1, 0) : mySide === 'w' ? vec(-1, 0) : mySide === 's' ? vec(0, 1) : vec(0, -1);
          const dirX = otherMouth.x - myMouth.x, dirY = otherMouth.y - myMouth.y;
          const gapLen = Math.hypot(dirX, dirY);
          const ux = gapLen > 1 ? dirX / gapLen : outVec.x;
          const uy = gapLen > 1 ? dirY / gapLen : outVec.y;
          const midMouth = vec((myMouth.x + otherMouth.x) / 2, (myMouth.y + otherMouth.y) / 2);
          const punch = thick + 90;
          const startInA = vec(myMouth.x - ux * punch, myMouth.y - uy * punch);
          const endInB = vec(otherMouth.x + ux * punch, otherMouth.y + uy * punch);
          // Only wall-frame true separated pass corridors (gapLen > 30); flush seams
          // already sit directly against both regions' perimeter walls!
          if (gapLen > 30) {
            walk.carveCorridor(myMouth.x, myMouth.y, midMouth.x, midMouth.y, bridgeHw + thick, 'wall', def.id);
            walk.carveCorridor(midMouth.x, midMouth.y, otherMouth.x, otherMouth.y, bridgeHw + thick, 'wall', otherId);
          }
          walk.carveCorridor(startInA.x, startInA.y, midMouth.x, midMouth.y, bridgeHw, 'ground', def.id);
          walk.carveCorridor(midMouth.x, midMouth.y, endInB.x, endInB.y, bridgeHw, 'ground', otherId);
          // Guarantee both inner tips join the main walkable interior mesh even if a
          // river bend or rock cluster sat near the border apron.
          if (!walk.isWalkable(startInA.x, startInA.y)) {
            const snapA = walk.snapToWalkable(startInA);
            walk.carveCorridor(startInA.x, startInA.y, snapA.x, snapA.y, Math.max(48, bridgeHw * 0.65), 'ground', def.id);
          }
          if (!walk.isWalkable(endInB.x, endInB.y)) {
            const snapB = walk.snapToWalkable(endInB);
            walk.carveCorridor(endInB.x, endInB.y, snapB.x, snapB.y, Math.max(48, bridgeHw * 0.65), 'ground', otherId);
          }
          for (const g of seam.extraGaps) {
            const gMid = vec((g.a.x + g.b.x) / 2, (g.a.y + g.b.y) / 2);
            const gA = isA ? g.a : g.b;
            const gB = isA ? g.b : g.a;
            walk.carveCorridor(gA.x - ux * (thick + 45), gA.y - uy * (thick + 45), gMid.x, gMid.y, g.halfW, 'ground', def.id);
            walk.carveCorridor(gMid.x, gMid.y, gB.x + ux * (thick + 45), gB.y + uy * (thick + 45), g.halfW, 'ground', otherId);
          }
          // Clear any blocking non-door scenery doodads inside the crossing throat.
          if (liveDoodads) {
            const clearHalf = Math.max(72, bridgeHw - 18);
            for (let i = liveDoodads.length - 1; i >= 0; i--) {
              const d = liveDoodads[i];
              if (d.door || d.anchor || d.kind === 'road' || d.kind === 'lantern_post' || d.kind === 'banner_post' || d.kind === 'signpost') continue;
              // Segment distance from d.pos to [startInA, endInB]
              const vx = endInB.x - startInA.x, vy = endInB.y - startInA.y;
              const l2 = vx * vx + vy * vy || 1;
              const proj = clamp(((d.pos.x - startInA.x) * vx + (d.pos.y - startInA.y) * vy) / l2, 0, 1);
              const cx = startInA.x + vx * proj, cy = startInA.y + vy * proj;
              if (Math.hypot(d.pos.x - cx, d.pos.y - cy) < clearHalf + d.radius * 0.5) {
                liveDoodads.splice(i, 1);
              }
            }
          }

          // Dress road flagstones / gravel discs + gateposts along the crossing!
          const distBetween = Math.hypot(otherMouth.x - myMouth.x, otherMouth.y - myMouth.y);
          const roadSteps = Math.max(2, Math.ceil(distBetween / 52));
          for (let s = 0; s <= roadSteps; s++) {
            const t = s / roadSteps;
            const rx = myMouth.x + (otherMouth.x - myMouth.x) * t;
            const ry = myMouth.y + (otherMouth.y - myMouth.y) * t;
            borderDoodads.push({
              pos: vec(rx, ry),
              radius: 34,
              kind: 'road',
              regionId: def.id,
              regionTheme: def.theme,
            });
          }
        }
      } else {
        // Locked crossing: reserve span from random clutter and plant gate markers.
        recordSpan(mySide, mySide === 'e' || mySide === 'w' ? myMouth.y : myMouth.x, SEAMLESS_CFG.mouthHalfW + 30);
      }

      // Gateposts / lanterns at sanctuary gates & chokepoint mouths!
      if (seam.style === 'sanctuary_gate' && def.id === START_ZONE) {
        const perp = mySide === 'e' || mySide === 'w' ? vec(0, 1) : vec(1, 0);
        const outDir = mySide === 'e' ? vec(1, 0) : mySide === 'w' ? vec(-1, 0) : mySide === 's' ? vec(0, 1) : vec(0, -1);
        for (const sgn of [-1, 1]) {
          borderDoodads.push({
            pos: vec(myMouth.x + perp.x * sgn * (SEAMLESS_CFG.sanctuaryGateHalfW + 18), myMouth.y + perp.y * sgn * (SEAMLESS_CFG.sanctuaryGateHalfW + 18)),
            radius: 12,
            kind: 'lantern_post',
            regionId: def.id,
            regionTheme: def.theme,
          });
          borderDoodads.push({
            pos: vec(myMouth.x + outDir.x * 28 + perp.x * sgn * (SEAMLESS_CFG.sanctuaryGateHalfW + 26), myMouth.y + outDir.y * 28 + perp.y * sgn * (SEAMLESS_CFG.sanctuaryGateHalfW + 26)),
            radius: 10,
            kind: 'banner_post',
            regionId: def.id,
            regionTheme: def.theme,
          });
        }
      } else if (seam.style === 'chokepoint_pass' && isA) {
        const perp = mySide === 'e' || mySide === 'w' ? vec(0, 1) : vec(1, 0);
        borderDoodads.push({
          pos: vec(myMouth.x + perp.x * (SEAMLESS_CFG.mouthHalfW + 22), myMouth.y + perp.y * (SEAMLESS_CFG.mouthHalfW + 22)),
          radius: 10,
          kind: 'signpost',
          regionId: def.id,
          regionTheme: def.theme,
        });
      }
    }

    // 3. Natural biome border dressing (trees, rocks, cliffs, walls) along closed runs
    //    so boundaries read as organic terrain rather than flat cut lines.
    const propKind = borderPropKindFor(def);
    const rng = new Rng((this.worldSeed ^ hashKey(def.id, 0x7b3d159f)) >>> 0);
    const inOpenSpan = (side: Dir, coord: number): boolean =>
      openSpans[side].some(sp => coord >= sp.lo && coord <= sp.hi);

    const dressEdge = (side: Dir): void => {
      const horiz = side === 'n' || side === 's';
      const lo = horiz ? x0 + 36 : y0 + 36;
      const hi = horiz ? x1 - 36 : y1 - 36;
      const fixed = side === 'n' ? y0 + 24 : side === 's' ? y1 - 24 : side === 'w' ? x0 + 24 : x1 - 24;
      const step = propKind === 'wall' ? 56 : 74;
      for (let c = lo; c <= hi; c += step) {
        const jitter = rng.range(-14, 14);
        const posC = c + jitter;
        if (inOpenSpan(side, posC)) continue;
        const px = horiz ? posC : fixed + rng.range(-8, 8);
        const py = horiz ? fixed + rng.range(-8, 8) : posC;
        const rad = propKind === 'forest_oak' || propKind === 'gloam_oak'
          ? rng.range(36, 52)
          : propKind === 'wall'
            ? 24
            : rng.range(20, 32);
        borderDoodads.push({
          pos: vec(px, py),
          radius: rad,
          kind: propKind,
          rot: rng.range(0, Math.PI * 2),
          regionId: def.id,
          regionTheme: def.theme,
        });
      }
    };

    dressEdge('n');
    dressEdge('s');
    dressEdge('e');
    dressEdge('w');

    walk.markDirtyRect(x0 - 120, y0 - 120, x1 + 120, y1 + 120);
    return borderDoodads;
  }

  /** Unseal a previously locked seam crossing in place once its lock clears! */
  openSeamInPlace(seam: SeamCrossing, walk: TiledWalkField, liveDoodads?: Doodad[]): void {
    seam.locked = false;
    const thick = SEAMLESS_CFG.borderWallThickPx;
    const hw = seam.flush ? SEAMLESS_CFG.mouthHalfW : SEAMLESS_CFG.passHalfW;
    const outVec = seam.sideOnA === 'e' ? vec(1, 0) : seam.sideOnA === 'w' ? vec(-1, 0) : seam.sideOnA === 's' ? vec(0, 1) : vec(0, -1);
    const dirX = seam.mouthB.x - seam.mouthA.x, dirY = seam.mouthB.y - seam.mouthA.y;
    const gapLen = Math.hypot(dirX, dirY);
    const ux = gapLen > 1 ? dirX / gapLen : outVec.x;
    const uy = gapLen > 1 ? dirY / gapLen : outVec.y;
    const mid = vec((seam.mouthA.x + seam.mouthB.x) / 2, (seam.mouthA.y + seam.mouthB.y) / 2);
    const sA = vec(seam.mouthA.x - ux * (thick + 90), seam.mouthA.y - uy * (thick + 90));
    const eB = vec(seam.mouthB.x + ux * (thick + 90), seam.mouthB.y + uy * (thick + 90));
    if (gapLen > 30) {
      walk.carveCorridor(seam.mouthA.x, seam.mouthA.y, mid.x, mid.y, hw + thick, 'wall', seam.aId);
      walk.carveCorridor(mid.x, mid.y, seam.mouthB.x, seam.mouthB.y, hw + thick, 'wall', seam.bId);
    }
    walk.carveCorridor(sA.x, sA.y, mid.x, mid.y, hw, 'ground', seam.aId);
    walk.carveCorridor(mid.x, mid.y, eB.x, eB.y, hw, 'ground', seam.bId);
    if (liveDoodads) {
      const clearHalf = Math.max(72, hw - 18);
      for (let i = liveDoodads.length - 1; i >= 0; i--) {
        const d = liveDoodads[i];
        if (d.door || d.kind === 'road' || d.kind === 'lantern_post' || d.kind === 'banner_post' || d.kind === 'signpost') continue;
        const vx = eB.x - sA.x, vy = eB.y - sA.y;
        const l2 = vx * vx + vy * vy || 1;
        const proj = clamp(((d.pos.x - sA.x) * vx + (d.pos.y - sA.y) * vy) / l2, 0, 1);
        const cx = sA.x + vx * proj, cy = sA.y + vy * proj;
        if (Math.hypot(d.pos.x - cx, d.pos.y - cy) < clearHalf + d.radius * 0.5) {
          liveDoodads.splice(i, 1);
        }
      }
    }
  }

  /** Spatial theme resolver for GroundRenderer: blends smoothly across shared
   *  region borders (`blendBandPx`) and tints outer wilderness aprons naturally. */
  sampleThemeAt(
    wx: number,
    wy: number,
    zoneMap: Record<string, ZoneDef>,
    fallback: ZoneTheme,
  ): ThemeBlendSample {
    let bestId: string | null = null;
    let bestDist = Infinity;
    let secondId: string | null = null;
    let secondDist = Infinity;

    for (const [id, s] of this.seats) {
      const box = { x0: s.originPx.x, y0: s.originPx.y, x1: s.originPx.x + s.w, y1: s.originPx.y + s.h };
      // Signed-like priority: inside a region's active box, measure inward depth as negative distance!
      let d: number;
      if (wx >= box.x0 && wx <= box.x1 && wy >= box.y0 && wy <= box.y1) {
        const edgeIn = Math.min(wx - box.x0, box.x1 - wx, wy - box.y0, box.y1 - wy);
        d = -edgeIn;
      } else {
        d = pointToRectDist(wx, wy, box);
      }
      if (d < bestDist) {
        secondDist = bestDist;
        secondId = bestId;
        bestDist = d;
        bestId = id;
      } else if (d < secondDist) {
        secondDist = d;
        secondId = id;
      }
    }

    const pDef = bestId ? zoneMap[bestId] : undefined;
    const primary = pDef?.theme ?? fallback;
    const seed = bestId ? (hashKey(bestId) % 100000) : 1337;

    if (!secondId || secondId === bestId) {
      return { primary, secondary: null, mix: 0, seed };
    }
    const sDef = zoneMap[secondId];
    if (!sDef || sDef.theme === primary) {
      return { primary, secondary: null, mix: 0, seed };
    }

    // Smoothly blend across the shared border band (`gap = secondDist - bestDist` -> 0 at midpoint).
    const gap = secondDist - bestDist;
    const band = SEAMLESS_CFG.blendBandPx;
    if (gap >= band) return { primary, secondary: null, mix: 0, seed };
    const t = clamp(0.5 * (1 - gap / band), 0, 0.5);
    // Smoothstep so the blend settles imperceptibly at both ends.
    const smooth = t * t * (3 - 2 * t) * 1.35;
    return {
      primary,
      secondary: sDef.theme,
      mix: clamp(smooth, 0, 0.5),
      seed,
    };
  }
}
